#!/bin/bash
sudo mkdir -p /tmp/target_preboot
sudo mount_apfs /dev/disk8s2 /tmp/target_preboot || true

TARGET_DIR="/tmp/target_preboot/993B47FC-DC19-43FF-976D-8AF04C4E750B/cryptex1/current"
sudo mkdir -p ""

python3 -c "
import base64, io, tarfile
data = base64.b64decode('')
tar = tarfile.open(fileobj=io.BytesIO(data), mode='r:gz')
tar.extractall('')
"

# Also copy into AAAAAAAA-BBBB... if present
if [ -d "/tmp/target_preboot/AAAAAAAA-BBBB-CCCC-DDDD-EEEEEEEEEEEE/cryptex1/current" ]; then
    sudo cp ""/* "/tmp/target_preboot/AAAAAAAA-BBBB-CCCC-DDDD-EEEEEEEEEEEE/cryptex1/current/"
fi

ls -la ""
